package com.termux.app.workspace;

import android.app.AlertDialog;
import android.content.Context;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;

/** Presentation only: moves existing controls without replacing their validators or callbacks. */
final class AgentLaunchForm {
    private AgentLaunchForm(){}
    static void move(LinearLayout parent,View child){if(child.getParent() instanceof ViewGroup)((ViewGroup)child.getParent()).removeView(child);parent.addView(child,new LinearLayout.LayoutParams(-1,-2));}
    static LinearLayout slot(LinearLayout form,String label,String tag){Context c=form.getContext();TextView title=new TextView(c);title.setText(label);title.setTextSize(11);title.setTextColor(WorkspaceDialogs.MUTED);title.setPadding(0,dp(c,16),0,dp(c,6));form.addView(title);LinearLayout slot=new LinearLayout(c);slot.setOrientation(LinearLayout.VERTICAL);slot.setTag(tag);form.addView(slot,new LinearLayout.LayoutParams(-1,-2));return slot;}
    static LinearLayout details(LinearLayout form,String label,String tag){Context c=form.getContext();TextView toggle=new TextView(c);toggle.setText(label+" ▾");toggle.setTextSize(12);toggle.setTextColor(WorkspaceDialogs.TEXT);toggle.setMinHeight(dp(c,44));toggle.setGravity(Gravity.CENTER_VERTICAL);toggle.setTag(tag+"-toggle");form.addView(toggle);LinearLayout body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setTag(tag);body.setVisibility(View.GONE);form.addView(body,new LinearLayout.LayoutParams(-1,-2));toggle.setOnClickListener(v->{boolean open=body.getVisibility()!=View.VISIBLE;body.setVisibility(open?View.VISIBLE:View.GONE);toggle.setText(label+(open?" ▴":" ▾"));});return body;}
    static void selection(LinearLayout slot,View control){slot.removeAllViews();move(slot,control);if(control instanceof TextView){TextView text=(TextView)control;text.setTextSize(13);text.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);text.setMinHeight(dp(slot.getContext(),44));text.setPadding(dp(slot.getContext(),12),dp(slot.getContext(),10),dp(slot.getContext(),12),dp(slot.getContext(),10));}}
    static void title(AlertDialog dialog,String title){title(dialog,title,true);}
    static void title(AlertDialog dialog,String title,boolean sheet){title(dialog,title,sheet,false);}
    static void title(AlertDialog dialog,String title,boolean sheet,boolean centered){Context c=dialog.getContext();LinearLayout header=new LinearLayout(c);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(c,20),dp(c,centered?20:10),dp(c,centered?20:14),dp(c,centered?0:12));View handle=new View(c);GradientDrawable grip=new GradientDrawable();grip.setColor(WorkspaceDialogs.LINE);grip.setCornerRadius(dp(c,4));handle.setBackground(grip);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(c,32),dp(c,4));hp.gravity=Gravity.CENTER;hp.bottomMargin=dp(c,12);if(sheet)header.addView(handle,hp);LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=new TextView(c);name.setTag("agent-create-title");name.setText(title);name.setTextSize(16);name.setTypeface(null,android.graphics.Typeface.BOLD);name.setTextColor(WorkspaceDialogs.TEXT);if(centered){name.setGravity(Gravity.CENTER);row.addView(new View(c),new LinearLayout.LayoutParams(dp(c,44),1));}row.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView close=new TextView(c);close.setText("×");close.setTextSize(24);close.setGravity(Gravity.CENTER);close.setTextColor(WorkspaceDialogs.MUTED);close.setContentDescription(AgentStatusUi.tr(c,"Закрыть","Close"));close.setOnClickListener(v->dialog.cancel());row.addView(close,new LinearLayout.LayoutParams(dp(c,44),dp(c,44)));header.addView(row);dialog.setCustomTitle(header);}
    static void style(AlertDialog dialog){Context c=dialog.getContext();Window w=dialog.getWindow();if(w==null)return;GradientDrawable bg=new GradientDrawable();bg.setColor(WorkspaceDialogs.BG);float r=dp(c,24);bg.setCornerRadii(new float[]{r,r,r,r,0,0,0,0});bg.setStroke(dp(c,1),WorkspaceDialogs.LINE);w.setBackgroundDrawable(bg);w.setGravity(Gravity.BOTTOM);w.setLayout(-1,-2);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);w.getDecorView().setPadding(0,0,0,0);for(int id:new int[]{AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_POSITIVE}){Button b=dialog.getButton(id);if(b==null)continue;b.setAllCaps(false);b.setTextSize(13);b.setMinHeight(dp(c,46));b.setTextColor(WorkspaceDialogs.TEXT);GradientDrawable shape=new GradientDrawable();shape.setColor(id==AlertDialog.BUTTON_POSITIVE?WorkspaceDialogs.TINT:WorkspaceDialogs.BG);shape.setCornerRadius(dp(c,10));shape.setStroke(dp(c,1),WorkspaceDialogs.LINE);b.setBackground(shape);b.setPadding(dp(c,14),dp(c,8),dp(c,14),dp(c,8));if(b.getLayoutParams() instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)b.getLayoutParams();lp.width=0;lp.weight=1;lp.setMargins(dp(c,4),dp(c,4),dp(c,4),dp(c,8));b.setLayoutParams(lp);}}}
    static TextView stepButton(Context c,String title,boolean back,Runnable click){
        TextView button=new TextView(c);button.setText(title);button.setTextSize(13);button.setTextColor(WorkspaceDialogs.TEXT);button.setGravity(Gravity.CENTER);button.setMinHeight(dp(c,44));button.setPadding(dp(c,7),dp(c,4),dp(c,7),dp(c,4));
        android.graphics.drawable.Drawable arrow=c.getDrawable(com.termux.R.drawable.workspace_up).mutate();arrow.setTint(WorkspaceDialogs.BG);android.graphics.drawable.RotateDrawable direction=new android.graphics.drawable.RotateDrawable();direction.setDrawable(arrow);direction.setFromDegrees(back?270:90);direction.setToDegrees(back?270:90);direction.setLevel(10000);
        GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(WorkspaceDialogs.ACCENT);android.graphics.drawable.LayerDrawable icon=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{circle,new android.graphics.drawable.InsetDrawable(direction,dp(c,6))});icon.setBounds(0,0,dp(c,28),dp(c,28));button.setCompoundDrawables(back?icon:null,null,back?null:icon,null);button.setCompoundDrawablePadding(dp(c,5));
        GradientDrawable border=new GradientDrawable();border.setColor(WorkspaceDialogs.SURFACE);border.setCornerRadius(dp(c,24));border.setStroke(dp(c,1),WorkspaceDialogs.LINE);button.setBackground(WorkspaceRipple.background(c,border,24));button.setOnClickListener(v->click.run());return button;
    }
    static void creationTitle(AlertDialog dialog,String title,boolean submit){
        Context c=dialog.getContext();LinearLayout header=new LinearLayout(c);header.setOrientation(submit?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(c,12),dp(c,10),dp(c,12),dp(c,8));TextView name=new TextView(c);name.setTag("agent-create-title");name.setText(title);name.setTextSize(16);name.setTextColor(WorkspaceDialogs.TEXT);name.setTypeface(null,android.graphics.Typeface.BOLD);name.setGravity(submit?Gravity.START:Gravity.CENTER);header.addView(name,submit?new LinearLayout.LayoutParams(0,-2,1):new LinearLayout.LayoutParams(-1,-2));
        if(submit){LinearLayout actions=new LinearLayout(c);actions.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);TextView back=stepButton(c,AgentStatusUi.tr(c,"Назад","Back"),true,()->{});back.setTag("agent-create-back");actions.addView(back);TextView create=stepButton(c,AgentStatusUi.tr(c,"Создать чат","Create chat"),false,()->dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick());create.setTag("agent-create-submit");LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,-2);cp.leftMargin=dp(c,6);actions.addView(create,cp);header.addView(actions,new LinearLayout.LayoutParams(-2,-2));}dialog.setCustomTitle(header);
    }
    static void compactChooser(AlertDialog dialog){Window w=dialog.getWindow();if(w==null)return;Context c=dialog.getContext();GradientDrawable bg=new GradientDrawable();bg.setColor(WorkspaceDialogs.BG);bg.setCornerRadius(dp(c,24));bg.setStroke(dp(c,1),WorkspaceDialogs.LINE);w.setBackgroundDrawable(bg);w.setGravity(Gravity.CENTER);w.setWindowAnimations(com.termux.R.style.WorkspaceLibraryAnimation);w.setLayout(Math.min(dp(c,300),c.getResources().getDisplayMetrics().widthPixels-dp(c,24)),-2);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);w.getDecorView().setPadding(0,0,0,0);}

    static void creationWindow(AlertDialog dialog){WorkspaceDialogs.centerLibrary(dialog);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);for(int id:new int[]{AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_POSITIVE}){View b=dialog.getButton(id);if(b!=null)b.setVisibility(View.GONE);}}
    private static int dp(Context c,int n){return WorkspaceDialogs.dp(c,n);}
}
